import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Garantiesystem für einen Weg für alle","description":"","frontmatter":{},"headers":[],"relativePath":"de/0008-人人有路保障体系.md","filePath":"de/0008-人人有路保障体系.md"}'),s={name:"de/0008-人人有路保障体系.md"};function a(l,e,u,d,o,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="garantiesystem-fur-einen-weg-fur-alle" tabindex="-1">Garantiesystem für einen Weg für alle <a class="header-anchor" href="#garantiesystem-fur-einen-weg-fur-alle" aria-label="Permalink to &quot;Garantiesystem für einen Weg für alle&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>08</td></tr><tr><td>Modul</td><td>Allgemeine Grundsätze und Kerneinstellungen</td></tr><tr><td>Schlüsselwörter</td><td>Ein Weg für alle, Garantiesystem, Evolutionsgrundlinie, Schwache Gruppen, Universal</td></tr></tbody></table><h2 id="i-grunddefinition-von-einem-weg-fur-alle" tabindex="-1">I. Grunddefinition von Einem Weg für alle <a class="header-anchor" href="#i-grunddefinition-von-einem-weg-fur-alle" aria-label="Permalink to &quot;I. Grunddefinition von Einem Weg für alle&quot;">​</a></h2><p>Ein Weg für alle ist eines der zentralen sozialen Ziele der Anker-Symbiotischen Zivilisation und bedeutet, sicherzustellen, dass jedes Leben in Heng Yuan Zhou, unabhängig von seiner Rasse, Herkunft, seinem Talent, seinem Niveau oder seiner Vermögenssituation, einen für sich geeigneten Evolutionsweg erhalten kann und die Gelegenheit hat, durch eigene Anstrengung eine Niveauerhöhung und Vervollkommnung des Lebens zu erreichen. &quot;Einen Weg haben&quot; bedeutet nicht nur, dass es Kultivierungsmethoden zum Lernen gibt, sondern auch, dass es Ressourcen zum Gebrauch, Mentoren zum Fragen, Umgebungen zum Kultivieren und Institutionen zum Verlassen gibt.</p><p>Ein Weg für alle und Mehr Arbeit, mehr Belohnung sind die zwei Säulen des Verteilungssystems der symbiotischen Zivilisation. Mehr Arbeit, mehr Belohnung löst das Problem der &quot;Effizienz&quot; und ermutigt die Starken, mehr Wert zu schaffen; Ein Weg für alle löst das Problem der &quot;Gerechtigkeit&quot; und stellt sicher, dass die Schwachen nicht vom Evolutionssystem im Stich gelassen werden. Beide ergänzen sich gegenseitig, und keines ist ohne das andere vollständig. Ohne einen Weg für alle würde Mehr Arbeit, mehr Belohnung zum Gesetz des Dschungels degenerieren; ohne Mehr Arbeit, mehr Belohnung würde Ein Weg für alle zum Egalitarismus degenerieren.</p><h2 id="ii-notwendigkeit-von-einem-weg-fur-alle" tabindex="-1">II. Notwendigkeit von Einem Weg für alle <a class="header-anchor" href="#ii-notwendigkeit-von-einem-weg-fur-alle" aria-label="Permalink to &quot;II. Notwendigkeit von Einem Weg für alle&quot;">​</a></h2><p>Die Einrichtung des Garantiesystems für einen Weg für alle basiert auf folgendem tiefen Verständnis:</p><h3 id="_2-1-das-evolutionsrecht-ist-das-grundlegendste-uberlebensrecht" tabindex="-1">2.1 Das Evolutionsrecht ist das grundlegendste Überlebensrecht <a class="header-anchor" href="#_2-1-das-evolutionsrecht-ist-das-grundlegendste-uberlebensrecht" aria-label="Permalink to &quot;2.1 Das Evolutionsrecht ist das grundlegendste Überlebensrecht&quot;">​</a></h3><p>In einer Kultivierungszivilisation ist das Evolutionsrecht nicht nur ein Entwicklungsrecht, sondern auch ein Überlebensrecht. Leben auf niedrigem Niveau hat, wenn es mit verschiedenen Gefahren im Kosmos konfrontiert ist (wie Ebenenschwankungen, Energiestürme, Invasionen fremder Rassen usw.), eine weit geringere Überlebenswahrscheinlichkeit als Leben auf hohem Niveau. Daher ist die Sicherstellung, dass jedes Leben einen Evolutionsweg hat, im Wesentlichen die Sicherstellung des grundlegenden Überlebensrechts jedes Lebens.</p><h3 id="_2-2-unterschiede-im-anfangstalent-sollten-das-evolutionsschicksal-nicht-bestimmen" tabindex="-1">2.2 Unterschiede im Anfangstalent sollten das Evolutionsschicksal nicht bestimmen <a class="header-anchor" href="#_2-2-unterschiede-im-anfangstalent-sollten-das-evolutionsschicksal-nicht-bestimmen" aria-label="Permalink to &quot;2.2 Unterschiede im Anfangstalent sollten das Evolutionsschicksal nicht bestimmen&quot;">​</a></h3><p>Jedes Leben hat große Unterschiede im Anfangstalent (Rassentalent, familiärer Hintergrund, Geburts ebene, angeborene Eignung usw.). In der Ära des Räuberismus wurden diese Unterschiede oft zu unüberwindbaren Gräben ausgeweitet — Leben mit guter Herkunft monopolisierten hochwertige Ressourcen, während Leben mit schlechter Herkunft nicht einmal grundlegende Kultivierungsmethoden erhalten konnten. Die symbiotische Zivilisation glaubt, dass Unterschiede im Anfangstalent objektiv existieren, aber nicht der einzige Faktor sein sollten, der das Evolutionsschicksal bestimmt. Die Rolle der Institution ist es, diese anfänglichen Unterschiede auszugleichen und jedem Leben die Gelegenheit zu geben, das Schicksal durch erworbene Anstrengung zu verändern.</p><h3 id="_2-3-im-stich-gelassene-individuen-sind-ein-potenzieller-verlust-fur-die-zivilisation" tabindex="-1">2.3 Im Stich gelassene Individuen sind ein potenzieller Verlust für die Zivilisation <a class="header-anchor" href="#_2-3-im-stich-gelassene-individuen-sind-ein-potenzieller-verlust-fur-die-zivilisation" aria-label="Permalink to &quot;2.3 Im Stich gelassene Individuen sind ein potenzieller Verlust für die Zivilisation&quot;">​</a></h3><p>Jedes Leben hat Evolutionspotenzial, und oft fehlt es nur an dem geeigneten Weg und den geeigneten Ressourcen. Ein Leben, das in der unteren Schicht kämpft, kann nach Erhalt eines geeigneten Kultivierungssystems erstaunliches Talent zeigen; ein Individuum, das als &quot;nutzlos&quot; gilt, hat vielleicht einfach noch nicht die für sich geeignete Evolutionsrichtung gefunden. Die Bedeutung des Garantiesystems für einen Weg für alle besteht darin, keinen potenziellen Evolutionär im Stich zu lassen und den Talentpool der Zivilisation so weit wie möglich zu erweitern.</p><h3 id="_2-4-universelle-evolution-ist-die-grundlage-fur-den-dimensionsaufstieg-des-kosmos" tabindex="-1">2.4 Universelle Evolution ist die Grundlage für den Dimensionsaufstieg des Kosmos <a class="header-anchor" href="#_2-4-universelle-evolution-ist-die-grundlage-fur-den-dimensionsaufstieg-des-kosmos" aria-label="Permalink to &quot;2.4 Universelle Evolution ist die Grundlage für den Dimensionsaufstieg des Kosmos&quot;">​</a></h3><p>Der globale Dimensionsaufstieg des Kosmos kann nicht nur von wenigen höchst starken Individuen abhängen, sondern erfordert die universelle Evolution der gewöhnlichen Wesen der Zehntausend Rassen. Die Effizienz des Ankerpunktnetzwerks korreliert positiv mit der Anzahl und Qualität der mit dem Netzwerk verbundenen Leben. Wenn mehr Leben mit dem Kultivierungssystem verbunden sind und ihr Niveau erhöhen, werden der Energiekreislauf und der Gesetzesbetrieb des gesamten Ankerpunktnetzwerks stabiler und effizienter, und der Prozess des Dimensionsaufstiegs des Kosmos wird schneller.</p><h2 id="iii-hierarchische-struktur-des-garantiesystems" tabindex="-1">III. Hierarchische Struktur des Garantiesystems <a class="header-anchor" href="#iii-hierarchische-struktur-des-garantiesystems" aria-label="Permalink to &quot;III. Hierarchische Struktur des Garantiesystems&quot;">​</a></h2><p>Das Garantiesystem für einen Weg für alle ist in vier Ebenen unterteilt und bildet eine vollständige Garantiekette von der Grundlage bis zur Fortgeschrittenen:</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Name</th><th>Garantieinhalt</th><th>Abdeckungsbereich</th></tr></thead><tbody><tr><td>Erste Ebene</td><td>Grundgarantie</td><td>Kostenlose Kultivierungsmethoden, Mindestressourcenverteilung, grundlegende medizinische und Bildungsdienstleistungen</td><td>Alle Leben, ohne Eintrittsschwelle</td></tr><tr><td>Zweite Ebene</td><td>Gezielte Unterstützung</td><td>Zusätzliche Ressourcen, Mentoren, technologische Unterstützung für schwache Gruppen</td><td>Individuen und Rassen mit schlechtem Anfangstalent</td></tr><tr><td>Dritte Ebene</td><td>Opportunitätserweiterung</td><td>Fortgeschrittene Kultivierungsmöglichkeiten, interplanarer Austausch, Teilnahmerecht an Sonderprojekten</td><td>Kultivierende mit Potenzial aber unzureichenden Ressourcen</td></tr><tr><td>Vierte Ebene</td><td>Leistungsanreiz</td><td>Hochwertige Ressourcen, erweiterter Zugang zu Ankerpunkten, Zivilehren</td><td>Kultivierende mit herausragenden Beiträgen</td></tr></tbody></table><p>Die erste Ebene ist die &quot;Grundlinie&quot;, die sicherstellt, dass niemand im Stich gelassen wird; die zweite Ebene ist der &quot;Differenzausgleich&quot;, der die Unterschiede im Anfangstalent ausgleicht; die dritte Ebene ist die &quot;Talentförderung&quot;, die Individuen mit Potenzial mehr Möglichkeiten gibt; die vierte Ebene ist der &quot;Anreiz&quot;, der herausragende Beitragende belohnt. Die vier Ebenen schreiten schrittweise voran und bilden ein vollständiges System aus Garantie und Anreiz.</p><h2 id="iv-spezifischer-inhalt-der-grundgarantie" tabindex="-1">IV. Spezifischer Inhalt der Grundgarantie <a class="header-anchor" href="#iv-spezifischer-inhalt-der-grundgarantie" aria-label="Permalink to &quot;IV. Spezifischer Inhalt der Grundgarantie&quot;">​</a></h2><p>Die Grundgarantie ist der Kern des Systems Ein Weg für alle und umfasst spezifisch folgenden Inhalt:</p><h3 id="_4-1-garantie-der-kultivierungsmethoden" tabindex="-1">4.1 Garantie der Kultivierungsmethoden <a class="header-anchor" href="#_4-1-garantie-der-kultivierungsmethoden" aria-label="Permalink to &quot;4.1 Garantie der Kultivierungsmethoden&quot;">​</a></h3><p>Die grundlegenden Methoden der Dreihundert Ursprungs-Kultivierungssysteme sind für alle Leben kostenlos geöffnet, ohne jegliche Eintrittsschwelle. Jedes Leben kann frei das für sich geeignete Kultivierungssystem wählen, ohne Gebühren zahlen zu müssen, ohne einer bestimmten Sekte beitreten zu müssen, ohne eine Eignungsprüfung durchlaufen zu müssen. Das Ankerpunktnetzwerk bietet eine Bewertung der Systemkompatibilität an und hilft dem Kultivierenden, den für sich am besten geeigneten Weg zu finden.</p><h3 id="_4-2-garantie-der-kultivierungsressourcen" tabindex="-1">4.2 Garantie der Kultivierungsressourcen <a class="header-anchor" href="#_4-2-garantie-der-kultivierungsressourcen" aria-label="Permalink to &quot;4.2 Garantie der Kultivierungsressourcen&quot;">​</a></h3><p>Durch den Mechanismus des produktionsgebundenen Vertrags und die öffentliche Ressourcenverteilung wird sichergestellt, dass jedes Leben die für die Aufrechterhaltung der grundlegenden Kultivierung erforderlichen Ressourcen erhält. Die grundlegende Ressourcenverteilung umfasst: Mindestenergieversorgung, grundlegende Kultivierungspillen, Nutzungsrecht an allgemeinen Kultivierungsgeräten. Für ebenen mit Ressourcenknappheit erfolgt eine interplanare Ressourcenzuweisung durch das Ankerpunktnetzwerk.</p><h3 id="_4-3-garantie-der-kultivierungsumgebung" tabindex="-1">4.3 Garantie der Kultivierungsumgebung <a class="header-anchor" href="#_4-3-garantie-der-kultivierungsumgebung" aria-label="Permalink to &quot;4.3 Garantie der Kultivierungsumgebung&quot;">​</a></h3><p>Die symbiotische Zivilisation hat auf jedem Planeten und jeder Ebene öffentliche Kultivierungsorte errichtet, darunter öffentliche Kultivierungsräume, Bereiche zur Regulierung der Energiekonzentration, Räume zur Wahrnehmung von Gesetzen usw. Diese Orte sind für alle Leben kostenlos oder zu niedrigen Preisen geöffnet und stellen sicher, dass selbst der ärmste Kultivierende eine geeignete Kultivierungsumgebung hat.</p><h3 id="_4-4-garantie-der-mentorenanleitung" tabindex="-1">4.4 Garantie der Mentorenanleitung <a class="header-anchor" href="#_4-4-garantie-der-mentorenanleitung" aria-label="Permalink to &quot;4.4 Garantie der Mentorenanleitung&quot;">​</a></h3><p>Es wird ein interrrassisches Mentorennetzwerk aufgebaut, und fortgeschrittene Kultivierende sind verpflichtet, Anfängerkultivierenden grundlegende Anleitung zu geben. Jeder Anfängerkultivier kann über das Ankerpunktnetzwerk eine Mentorenzuordnung beantragen und kostenlos grundlegende Antworten auf Fragen und Kultivierungsratschläge erhalten. Für Kultivierende mit besonderen Schwierigkeiten wird eine gezielte Einzelanleitung bereitgestellt.</p><h3 id="_4-5-garantie-der-medizinischen-rehabilitation" tabindex="-1">4.5 Garantie der medizinischen Rehabilitation <a class="header-anchor" href="#_4-5-garantie-der-medizinischen-rehabilitation" aria-label="Permalink to &quot;4.5 Garantie der medizinischen Rehabilitation&quot;">​</a></h3><p>Das symbiotische medizinische System bietet Kultivierenden kostenlose grundlegende medizinische und Rehabilitationsdienstleistungen bei Kultivierungsabweichungen an. Bei Verletzungen, Kultivierungsabweichungen, Energiestörungen usw. während des Kultivierungsprozesses kann eine rechtzeitige Behandlung und Rehabilitationsunterstützung erhalten werden, um sicherzustellen, dass der Kultivierende nicht durch Unfälle die Evolutionsfähigkeit verliert.</p><h2 id="v-ziele-und-methoden-der-gezielten-unterstutzung" tabindex="-1">V. Ziele und Methoden der gezielten Unterstützung <a class="header-anchor" href="#v-ziele-und-methoden-der-gezielten-unterstutzung" aria-label="Permalink to &quot;V. Ziele und Methoden der gezielten Unterstützung&quot;">​</a></h2><p>Die gezielte Unterstützung richtet sich an folgende schwache Gruppen:</p><ul><li><strong>Individuen mit geringem Talent</strong>: Individuen mit schlechter angeborener Eignung und langsamem Kultivierungsfortschritt, die zusätzliche Ressourcenverteilung und personalisierte Anleitung erhalten</li><li><strong>Arme Rassen</strong>: Rassen mit allgemeinem Ressourcenmangel und niedrigem Evolutionsniveau, die gezielte Unterstützung aus dem Rassenentwicklungsfonds erhalten</li><li><strong>Gruppen nach Katastrophen</strong>: Gruppen, die durch Ebenenkatastrophen, Kriege usw. ihr Zuhause und ihre Ressourcen verloren haben, die Notfallhilfe und Wiederaufbauunterstützung erhalten</li><li><strong>Kultivierende mit Behinderungen</strong>: Kultivierende mit körperlichen oder geistigen Behinderungen aus verschiedenen Gründen, die spezielle Kultivierungshilfsgeräte und personalisierte Kultivierungspläne erhalten</li><li><strong>Anomales Leben</strong>: Anomales Leben, das nicht zu den üblichen Kultivierungssystemen passt, das eine spezielle Bewertung und einen personalisierten Evolutionsweg erhält</li></ul><p>Die Methoden der gezielten Unterstützung umfassen: zusätzliche Ressourcenverteilung, Einzel-Mentorenanleitung, personalisierte Kultivierungspläne, Bereitstellung spezieller Geräte, Möglichkeiten des interplanaren Austauschs usw. Das Ziel der Unterstützung ist es, den schwachen Gruppen zu helfen, das grundlegende Evolutionsniveau zu erreichen, und dann schrittweise zum normalen System der Verteilung von Mehr Arbeit, mehr Belohnung überzugehen.</p><h2 id="vi-quellen-der-mittel-und-ressourcen-des-garantiesystems" tabindex="-1">VI. Quellen der Mittel und Ressourcen des Garantiesystems <a class="header-anchor" href="#vi-quellen-der-mittel-und-ressourcen-des-garantiesystems" aria-label="Permalink to &quot;VI. Quellen der Mittel und Ressourcen des Garantiesystems&quot;">​</a></h2><p>Der Betrieb des Garantiesystems für einen Weg für alle erfordert viele Ressourcen und Mittel, und seine Quellen umfassen:</p><ol><li><strong>Einnahmen aus öffentlichen Ressourcen</strong>: Produktion aus Ressourcen wie öffentlichen spirituellen Adern, Energieerzadern, Heilfeldern usw., die direkt von der symbiotischen Zivilisation verwaltet werden</li><li><strong>Beitragsregulierungssteuer</strong>: Erhebung eines bestimmten Anteils der &quot;Beitragsregulierungssteuer&quot; von Hochbeitragenden, die für den Betrieb des Garantiesystems verwendet wird (Steuersatz progressiv, maximal nicht über 30%)</li><li><strong>Zivilisationsentwicklungsfonds</strong>: Überschüssige Energie, die durch den Betrieb des Ankerpunktnetzwerks erzeugt wird, ein Teil davon fließt in den Zivilisationsentwicklungsfonds</li><li><strong>Einnahmen aus Technologielizenzen</strong>: Nutzungsgebühren für Lizenzen der im Besitz der symbiotischen Zivilisation befindlichen Gesetzestechnologien</li><li><strong>Spenden und Vermächtnisse</strong>: Freiwillige Spenden von Individuen und Rassen</li></ol><p>Die Einnahmen und Ausgaben des Garantiesystems werden vom Garantieausschuss unter dem Parlament der Republik der Zehntausend Rassen verwaltet, und die Konten werden regelmäßig allen Leben veröffentlicht und unterliegen der Aufsicht.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Das Garantiesystem für einen Weg für alle ist der Grundstein der sozialen Gerechtigkeit der Anker-Symbiotischen Zivilisation. Es stellt sicher, dass in einer Zivilisation, die sich auf Kultivierung und Evolution konzentriert, kein Leben aufgrund von Herkunft, Talent oder Armut vom Evolutionssystem im Stich gelassen wird. Ein Weg für alle bedeutet nicht, Egalitarismus zu praktizieren, sondern jedem Leben einen fairen Startpunkt, einen Aufstiegskanal und ein Versprechen, nicht im Stich gelassen zu werden, zu geben. Unter der Garantie von Einem Weg für alle kann jedes Leben seinen eigenen Evolutionsweg finden.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Prinzip der Verteilung von Mehr Arbeit, Mehr Belohnung)</li><li>07-自生自长进化法则 (Gesetz der selbstgenerierten und selbstgewachsenen Evolution)</li><li>38-共生医疗体系 (Symbiotisches Medizinisches System)</li></ul>',43)])])}const m=n(s,[["render",a]]);export{c as __pageData,m as default};
